        uint32_t s0_2=ROR(x2,7)^ROR(x2,18)^(x2>>3);
        uint32_t s0_3=ROR(x3,7)^ROR(x3,18)^(x3>>3);
        uint32_t s1_2=ROR(y2,17)^ROR(y2,19)^(y2>>10);
        uint32_t s1_3=ROR(y3,17)^ROR(y3,19)^(y3>>10);
        w[i+2] = w[i-14]+s0_2+w[i-5]+s1_2;
        w[i+3] = w[i-13]+s0_3+w[i-4]+s1_3;
    }
    uint32_t a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    #pragma unroll
    for(int i=0;i<64;i++){
        uint32_t S1=ROR(e,6)^ROR(e,11)^ROR(e,25);
        uint32_t ch=(e&f)^((~e)&g);
        uint32_t t1=h+S1+ch+K[i]+w[i];
        uint32_t S0=ROR(a,2)^ROR(a,13)^ROR(a,22);
        uint32_t maj=(a&b)^(a&c)^(b&c);
