void sha256_fast(const uint8_t *data, size_t len, uint8_t out[32]){
    uint32_t H[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t off=0;
    while(len-off>=64){ compress(H, data+off); off+=64; }
    uint8_t tail[128]; memset(tail,0,128);
    size_t rem=len-off; memcpy(tail,data+off,rem); tail[rem]=0x80;
    uint64_t bitlen=(uint64_t)len*8;
    size_t padblocks=(rem+9<=64)?64:128;
    for(int i=0;i<8;i++) tail[padblocks-1-i]=(uint8_t)((bitlen>>(8*i))&0xff);
    for(size_t t=0;t<padblocks;t+=64) compress(H, tail+t);
    for(int i=0;i<8;i++){ out[4*i]=H[i]>>24; out[4*i+1]=(H[i]>>16)&255; out[4*i+2]=(H[i]>>8)&255; out[4*i+3]=H[i]&255; }
}

